css:
/* Base card layout */
.weather-card-full-cycle {
  position: relative;
  width: 450px;
  height: 250px;
  border-radius: 45px;
  padding: 30px;
  box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica,
    Arial, sans-serif;
  color: #ffffff;
  overflow: hidden;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.25);
}

/* Thick white inner framing overlay */
.weather-card-full-cycle::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 45px;
  box-shadow: inset 0 0 0 8px rgba(255, 255, 255, 1);
  pointer-events: none;
  z-index: 20;
}

/* --- Environmental Background Layers --- */
.bg-dawn,
.bg-day,
.bg-night {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.bg-dawn {
  background: linear-gradient(180deg, #81569d 0%, #d86968 45%, #f4aa5b 100%);
  animation: fadeDawn 12s ease-in-out infinite alternate;
}

.bg-day {
  background: linear-gradient(180deg, #3fa1df 0%, #6ec2f2 45%, #bce2f7 100%);
  animation: fadeDay 12s ease-in-out infinite alternate;
}

.bg-night {
  background: radial-gradient(circle at 50% 0%, #333333 0%, #0a0a0a 100%);
  animation: fadeNight 12s ease-in-out infinite alternate;
}

/* --- Content Layout & Typography --- */
.card-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  position: absolute;
  top: 30px;
  left: 30px;
  right: 30px;
  z-index: 10;
}

.header-dawn {
  animation: fadeDawn 12s ease-in-out infinite alternate;
}
.header-day {
  animation: fadeDay 12s ease-in-out infinite alternate;
}
.header-night {
  animation: fadeNight 12s ease-in-out infinite alternate;
}

.title-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.status-text {
  font-size: 34px;
  font-weight: 600;
  margin: 0;
  letter-spacing: -0.5px;
}

.subtitle-text {
  font-size: 14px;
  color: rgba(255, 255, 255, 0.7);
  margin: 0;
}

.temperature-text {
  font-size: 26px;
  font-weight: 400;
  letter-spacing: -0.5px;
}

/* --- Geometric Orbit System Alignment --- */
.orbit-system {
  position: absolute;
  top: 110px; /* Defines the absolute apex height of the path */
  left: 50%;
  transform: translateX(-50%);
  width: 480px; /* Extends slightly past 450px card to curve gracefully into corners */
  height: 480px;
  z-index: 5;
}

.orbit-path {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 12px solid rgba(255, 255, 255, 0.25);
  box-sizing: border-box; /* Locks border within container bounds */
  -webkit-mask-image: linear-gradient(
    to right,
    transparent 10%,
    black 40%,
    black 60%,
    transparent 90%
  );
  mask-image: linear-gradient(
    to right,
    transparent 10%,
    black 40%,
    black 60%,
    transparent 90%
  );
}

.celestial-pivot {
  position: absolute;
  inset: 0;
  transform-origin: center center;
  animation: orbitSweep 12s ease-in-out infinite alternate;
}

.celestial-body {
  position: absolute;
  /* Centering formula: Top border width center line (6px) minus half element height (16px) = -10px */
  top: -10px;
  left: 50%;
  margin-left: -16px; /* Horizontal offset handles centering to protect rotation physics */
  width: 32px;
  height: 32px;
  background: #ffffff;
  border-radius: 50%;
  animation: celestialGlow 12s ease-in-out infinite alternate;
}

/* --- Keyframe Synchronization --- */
@keyframes fadeDawn {
  0%,
  15% {
    opacity: 1;
    transform: translateY(0);
  }
  40%,
  100% {
    opacity: 0;
    transform: translateY(-10px);
  }
}

@keyframes fadeDay {
  0%,
  15% {
    opacity: 0;
    transform: translateY(10px);
  }
  40%,
  60% {
    opacity: 1;
    transform: translateY(0);
  }
  85%,
  100% {
    opacity: 0;
    transform: translateY(-10px);
  }
}

@keyframes fadeNight {
  0%,
  60% {
    opacity: 0;
    transform: translateY(10px);
  }
  85%,
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes orbitSweep {
  0%,
  15% {
    transform: rotate(-65deg);
  } /* Dawn Phase (Left side of arc) */
  40%,
  60% {
    transform: rotate(0deg);
  } /* Day Phase (Apex peak center) */
  85%,
  100% {
    transform: rotate(65deg);
  } /* Night Phase (Right side of arc) */
}

@keyframes celestialGlow {
  0%,
  15% {
    box-shadow:
      0 0 20px 10px rgba(255, 255, 255, 0.7),
      0 0 45px 25px rgba(254, 180, 100, 0.6);
  }
  40%,
  60% {
    box-shadow:
      0 0 25px 15px rgba(255, 255, 255, 0.9),
      0 0 60px 30px rgba(255, 235, 130, 0.6);
  }
  85%,
  100% {
    box-shadow:
      0 0 20px 10px rgba(255, 255, 255, 0.8),
      0 0 40px 20px rgba(200, 220, 255, 0.3);
  }
}
